@Configuration
@EnableMethodSecurity
public class SecurityConfiguration {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            .authorizeHttpRequests(auth -> auth
                // Using an Authority for fine-grained resource access
                .requestMatchers("/api/v1/audits/**").hasAuthority("AUDIT_READ")
                // Using a Role for broad administrative surface areas
                .requestMatchers("/api/v1/admin/**").hasRole("ADMIN")
                .anyRequest().authenticated()
            );
        return http.build();
    }

    @PreAuthorize("hasAuthority('USER_MODIFY') or hasRole('SUPERVISOR')")
    public void updateManagedUser(Long userId, UserUpdateDto dto) {
        // Business logic for updating a user profile
    }
}
